from robot.libraries.BuiltIn import BuiltIn
from taf.sw.reporting_portal.api import reporting_portal

from taf.rfrl.procedures.resources.python.logger import log_input_and_output


class SingletonKPI(object):
    """Singleton class"""

    _instance = None
    _list_of_kpi = []

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(SingletonKPI, cls).__new__(cls)
        return cls._instance

    @property
    def list_of_kpi(self):
        return self._list_of_kpi

    def reset_list_of_kpi(self):
        self._list_of_kpi = []

    def append_kpi(self, target, name, value):
        """
        Append KPI results of keyword with provided name to list.

        :param target: Maximum possible target value that keyword might reach.
        :type target: str
        :param name: name of KPI.
        :type name: str
        :param value: Value.
        :type value: str
        """
        self._list_of_kpi.append(
            self._get_kpi_dict(target=target, name=name, value=value)
        )

    def report_kpi_to_rp(self, target, name, value):
        """
        Keyword to report KPI results of keyword with provided name.
        Reports are sent to Unified Test Environment's Reporting Portal.

        :param target: Maximum possible target value that keyword might reach.
        :type target: str
        :param name: name of KPI.
        :type name: str
        :param value: Value.
        :type value: str
        :note: KPI results are not reported immediately.
               KPI results will be read by ute_reporting_portal script and will be added to robot report.
        """
        ute = reporting_portal()

        dict_of_kpi = self._get_kpi_dict(target=target, name=name, value=value)

        ute.report_kpi_results(**dict_of_kpi)

    @staticmethod
    @log_input_and_output
    def _get_kpi_dict(target, name, value):
        return {
            "target": str(target),
            "name": str(name),
            "visible_to_db": "True",
            "value": str(value),
            "type": "float",
            "description": str(
                BuiltIn().get_variable_value(
                    "${TEST_NAME}", default="Common Suite Setup"
                )
            ),
            "category": "SISO_KPI",
            "unit": "seconds",
        }
